// Resolve WHICH campaign and WHICH movie this run operates on — without ever
// creating a duplicate campaign (the v1 import-per-run mistake).
//   campaign: target.campaignId → derived from target.movieId → adopt-by-name
//             via list-campaign → import ONCE
//   movie:    patch   → target.movieId || the trailer/template movie
//             episode → lowest unrendered slot || create-new-season || bootstrap
const base = $env.YAKYAK_API_BASE || 'https://api.yakyak.ai';
const token = $env.YAKYAK_TOKEN;
const body = $('Input event').first().json.body || {};
const target = body.target || {};
const mode = target.mode || 'patch';
if (mode !== 'patch' && mode !== 'episode') throw new Error(`unknown target.mode "${mode}" (use "patch" or "episode")`);

// The PAT is yy_live_ + a JWT whose payload carries the userId in its `id` claim.
let userId = $env.YAKYAK_USER_ID || '';
if (!userId) {
  try {
    const payload = (token || '').replace(/^yy_live_/, '').split('.')[1];
    userId = JSON.parse(Buffer.from(payload, 'base64url').toString('utf8')).id || '';
  } catch {}
}
if (!userId) throw new Error('Could not decode a userId from YAKYAK_TOKEN (malformed token?)');

const req = (method, path, bodyJson) => this.helpers.httpRequest({
  method, url: base + path,
  headers: { Authorization: 'Bearer ' + token, ...(bodyJson ? { 'Content-Type': 'application/json' } : {}) },
  body: bodyJson, json: true,
});
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// ---- campaign: reuse before create ----------------------------------------
const list = await req('GET', `/workflow/list-campaign/${userId}`);
const owned = list.campaigns || [];
let campaignId = target.campaignId || '';
let listEntry = null;
let provisioned = 'reused';
if (!campaignId && target.movieId) {
  // Movie-id-only call (e.g. "patch this grid movie"): derive the campaign
  // from the movie itself — the caller shouldn't need to know it.
  const gotMovie = await req('GET', `/workflow/get-movie/${target.movieId}`);
  campaignId = ((gotMovie.movie || gotMovie).campaignId) || '';
  if (!campaignId) throw new Error(`get-movie ${target.movieId} returned no campaignId`);
}
if (campaignId) {
  listEntry = owned.find((c) => c.id === campaignId) || null;
  if (!listEntry) throw new Error(`campaign ${campaignId} is not owned by this token's user`);
} else {
  const name = target.campaignName || (body.importData && body.importData.campaigns && body.importData.campaigns[0] && body.importData.campaigns[0].name) || '';
  if (!name) throw new Error('need target.campaignId, target.campaignName, or importData to resolve a campaign');
  // Oldest name match = the canonical original (later same-name copies are
  // v1-era import duplicates). Deterministic across runs.
  const matches = owned.filter((c) => c.name === name)
    .sort((a, b) => String(a.createdAt).localeCompare(String(b.createdAt)));
  if (matches.length) {
    listEntry = matches[0];
    campaignId = listEntry.id;
  } else if (body.importData) {
    const imported = await req('POST', '/workflow/import-campaign', { userId, importData: body.importData });
    campaignId = imported.campaigns && imported.campaigns[0] && imported.campaigns[0].id;
    if (!campaignId) throw new Error('import-campaign returned no campaign');
    provisioned = 'imported';
  } else {
    throw new Error(`no owned campaign named "${name}" and no importData to provision one`);
  }
}

// ---- movie -----------------------------------------------------------------
const fetchMovies = async () => {
  const got = await req('GET', `/workflow/get-campaign/${campaignId}`);
  return ((got.campaign || got).movies || [])
    .slice()
    .sort((a, b) => (Number(a.season) - Number(b.season)) || (Number(a.episode) - Number(b.episode)));
};
let movies = await fetchMovies();
let movieId = '';

if (mode === 'patch') {
  // Patch default is the TRAILER/TEMPLATE — the campaign's stable face. Numbered
  // episodes must be pinned via target.movieId (auto-picking S1E1 out of a grid
  // of episodes was a footgun). Note: get-campaign lists only numbered episodes;
  // the trailer comes from list-campaign's entry.template.id.
  const templateId = (listEntry && listEntry.template && listEntry.template.id) || '';
  if (target.movieId) {
    if (!movies.some((m) => m.id === target.movieId) && target.movieId !== templateId) {
      throw new Error(`movie ${target.movieId} not found in campaign ${campaignId} (${movies.length} episode(s); template: ${templateId || 'none'})`);
    }
    movieId = target.movieId;
  } else if (templateId) {
    movieId = templateId;
  } else if (movies.length === 1) {
    movieId = movies[0].id; // no template and exactly one movie — unambiguous
  } else if (movies.length === 0) {
    throw new Error(`campaign ${campaignId} has no template movie and no episodes to patch`);
  } else {
    const list = movies.map((m) => `S${m.season}E${m.episode}=${m.id}`).join(', ');
    throw new Error(`campaign ${campaignId} has no template movie and ${movies.length} episodes — pass target.movieId. Candidates: ${list}`);
  }
} else {
  // episode mode: generation auto-chains only in basic mode. Best-effort — we
  // own the campaign, but don't fail the run over it.
  try { await req('POST', '/workflow/switch-campaign-mode', { campaignId, mode: 'basic' }); } catch {}
  const nextSlot = (ms) => ms.find((m) => !(m.renderedMovieUrl || ''));
  let slot = nextSlot(movies);
  if (!slot) {
    if (movies.length > 0) {
      // every slot rendered → mint the next season
      await req('POST', '/workflow/create-new-season', { campaignId });
    } else {
      // fresh campaign, no numbered slots: create-new-season can't bootstrap
      // from nothing (it 500s) — seed season 1 from the template movie.
      const templateId = listEntry && listEntry.template && listEntry.template.id;
      if (!templateId) throw new Error('campaign has no episode slots and no template movie to bootstrap from');
      await req('POST', '/workflow/gen-movie-season', { movieId: templateId });
    }
    // Code nodes are time-capped (~60s under task runners), so wait briefly
    // here and tell the caller to retry if slots are still materialising.
    for (let i = 0; i < 8 && !slot; i++) { await sleep(5000); movies = await fetchMovies(); slot = nextSlot(movies); }
    if (!slot) throw new Error('season creation is still in progress — re-run in a minute and it will pick up the new slot');
  }
  movieId = slot.id;
}

return [{ json: { userId, base, mode, campaignId, movieId, provisioned, chatWebhookUrl: body.chatWebhookUrl || '' } }];

// PATCH mode: apply each change via the update-scene-* endpoint that both
// persists the edit AND self-triggers the right regen cascade — skipping no-ops
// (compared against current values) so a re-delivered trigger event doesn't
// re-bill unchanged scenes (a redundant `story` costs an AI image gen).
// EPISODE mode: write the new slot's plot and kick gen-movie-screenplay, which
// writes the whole screenplay AND renders every scene server-side (💸).
const t = $('Resolve target').first().json;
const base = t.base, movieId = t.movieId, mode = t.mode;
const token = $env.YAKYAK_TOKEN;
const changes = ($('Input event').first().json.body.changes) || {};
const req = (path, body) => this.helpers.httpRequest({
  method: 'POST', url: base + path,
  headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' },
  body, json: true,
});

let changed = 0;

if (changes.movie && changes.movie.title) {
  await req('/workflow/update-movie-title', { movieId, title: changes.movie.title });
}
// Optional soundtrack pin (content-address reuse — no upload, no generation).
// The path is a CDN content address; env prefixes (beta/, prd/) resolve in the
// shared bucket regardless of which env the campaign lives in (docs/forking.md).
if (changes.movie && changes.movie.soundtrackAudioPath) {
  await req('/workflow/set-soundtrack-audio', { movieId, audioPath: changes.movie.soundtrackAudioPath });
}
if (changes.movie && changes.movie.soundtrackVolume != null) {
  await req('/workflow/set-soundtrack', { movieId, volumePercentage: Number(changes.movie.soundtrackVolume) });
}

if (mode === 'episode') {
  if (!changes.movie || !changes.movie.plot) throw new Error('episode mode needs changes.movie.plot (the story text for the new episode)');
  await req('/workflow/set-movie-metadata', { movieId, plot: changes.movie.plot });
  await req('/workflow/gen-movie-screenplay', { movieId });
  return [{ json: { movieId, mode, changed: 1 } }];
}

const sceneChanges = changes.scenes || [];
const scenes = $('Get scenes').first().json.scenes || [];
const byNumber = {};
for (const s of scenes) byNumber[s.sceneNumber] = s;

for (const ch of sceneChanges) {
  const scene = byNumber[ch.sceneNumber];
  if (!scene) continue;
  const sceneId = scene.id;
  switch (ch.action) {
    case 'story':
      if (scene.story === ch.story) continue; // no-op: skip
      await req('/workflow/update-scene-story', { sceneId, story: ch.story }); break;
    case 'dialogue':
      if (scene.dialogue === ch.dialogue) continue;
      await req('/workflow/update-scene-dialogue', { sceneId, dialogue: ch.dialogue }); break;
    case 'animation': // current prompt isn't exposed by get-scenes; always apply
      await req('/workflow/update-scene-animation-prompt', { sceneId, prompt: ch.prompt }); break;
    case 'styling': {
      let did = false;
      if (ch.leadCast != null && ch.leadCast !== scene.leadCast) {
        await req('/workflow/update-scene-lead-cast', { sceneId, leadCast: ch.leadCast }); did = true;
      }
      if (ch.backgroundColor != null) {
        await req('/workflow/update-scene-background-color', { sceneId, backgroundColor: ch.backgroundColor });
        await req('/workflow/rerun-scene', { sceneId, from: 'subtitle' }); did = true;
      }
      if (!did) continue;
      break;
    }
    case 'title':
      if (scene.title === ch.title) continue;
      await req('/workflow/update-scene-title', { sceneId, title: ch.title }); break;
    case 'retry': await req('/workflow/rerun-scene', { sceneId, from: ch.from || 'image' }); break;
    case 'regen': await req('/workflow/regen-scene-asset', { sceneId, asset: ch.asset || 'image' }); break;
    default: throw new Error(`unknown action "${ch.action}" for scene ${ch.sceneNumber}`);
  }
  changed++;
}
return [{ json: { movieId, mode, changed } }];

// PATCH: nothing changed → nothing to wait for (mirrors the reference script;
// a movie can legitimately report a stage as forever-pending — the dialogue-less
// outro scene has no subtitle/burn asset, so those stages sit at N-1/N with 0
// failed). Otherwise settled when done+failed >= total everywhere.
// EPISODE: the web app's completion signal — movieScreenplay completing;
// export-render then finishes any per-scene renders still in flight.
const mode = $('Resolve target').first().json.mode;
const changed = $('Apply changes').first().json.changed || 0;
if (changed === 0) return [{ json: { settled: true, failed: 0 } }];
if (mode === 'episode') {
  const ex = {};
  for (const e of ($json.executions || [])) ex[e.type] = e.status;
  if (ex.movieScreenplay === 'failed') throw new Error('screenplay generation failed');
  return [{ json: { settled: ex.movieScreenplay === 'completed', failed: 0 } }];
}
const steps = Object.values($json.steps || {});
const settled = steps.length === 0 || steps.every((s) => s.total === 0 || (s.done + s.failed) >= s.total);
const failed = steps.reduce((n, s) => n + (s.failed || 0), 0);
return [{ json: { settled, failed } }];

const ex = {};
for (const e of ($json.executions || [])) ex[e.type] = e.status;
if (ex.movieConcat === 'failed' || ex.movieSoundtrack === 'failed') throw new Error('render failed');
const done = ex.movieConcat === 'completed' && (ex.movieSoundtrack === undefined || ex.movieSoundtrack === 'completed');
return [{ json: { done } }];
